mkdir -p "$HOME/.mobilessh/langchain"; cat > "$HOME/.mobilessh/langchain/app.py" <<'PYEOF'
import os
from fastapi import FastAPI
from pydantic import BaseModel
from langchain_ollama import ChatOllama, OllamaEmbeddings
from langchain_chroma import Chroma
from langchain_community.document_loaders import DirectoryLoader, TextLoader
from langchain_text_splitters import RecursiveCharacterTextSplitter
from langchain_core.prompts import ChatPromptTemplate
from langchain_core.runnables import RunnablePassthrough
from langchain_core.output_parsers import StrOutputParser

DOCS = os.path.expanduser(os.environ.get("RAG_DOCS", "~/rag-docs"))
DBDIR = os.path.expanduser("~/.mobilessh/langchain/chroma")
MODEL = os.environ.get("RAG_MODEL", "llama3.1")
EMBED = os.environ.get("RAG_EMBED", "nomic-embed-text")
OLLAMA = os.environ.get("OLLAMA_BASE_URL", "http://127.0.0.1:11434")

emb = OllamaEmbeddings(model=EMBED, base_url=OLLAMA)
llm = ChatOllama(model=MODEL, base_url=OLLAMA)
store = Chroma(collection_name="docs", embedding_function=emb, persist_directory=DBDIR)
prompt = ChatPromptTemplate.from_template(
    "Answer the question using only the context.\n\nContext:\n{context}\n\nQuestion: {question}")


def fmt(d):
    return "\n\n".join(x.page_content for x in d)


def ingest():
    # Rebuild from scratch so repeated /reindex calls do not duplicate vectors.
    global store
    try:
        store.delete_collection()
    except Exception:
        pass
    store = Chroma(collection_name="docs", embedding_function=emb, persist_directory=DBDIR)
    os.makedirs(DOCS, exist_ok=True)
    docs = []
    for g in ("**/*.md", "**/*.txt"):
        try:
            docs += DirectoryLoader(DOCS, glob=g, loader_cls=TextLoader, silent_errors=True).load()
        except Exception:
            pass
    if docs:
        chunks = RecursiveCharacterTextSplitter(chunk_size=1000, chunk_overlap=150).split_documents(docs)
        store.add_documents(chunks)


app = FastAPI()


@app.on_event("startup")
def _boot():
    # Index whatever is already in DOCS so the first query has context.
    try:
        ingest()
    except Exception:
        pass


class Q(BaseModel):
    query: str


@app.get("/health")
def health():
    return {"ok": True}


@app.post("/reindex")
def reindex():
    ingest()
    return {"ok": True}


@app.post("/query")
def query(q: Q):
    retr = store.as_retriever()
    chain = {"context": retr | fmt, "question": RunnablePassthrough()} | prompt | llm | StrOutputParser()
    return {"response": chain.invoke(q.query)}
PYEOF
